import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
B="http://localhost:8080"
tok=[None]
def newtok():
    r=urllib.request.Request(B+"/token",method="POST")
    tok[0]=json.load(urllib.request.urlopen(r))["token"]
def get(path):
    for attempt in range(200):
        if tok[0] is None: newtok()
        r=urllib.request.Request(B+path,headers={"Authorization":"Bearer "+tok[0]})
        try:
            return json.load(urllib.request.urlopen(r))
        except urllib.error.HTTPError as e:
            body=e.read().decode()
            if e.code==404: return None
            if e.code==401: newtok(); continue
            if e.code==429:
                w=e.headers.get("Retry-After")
                try: w=float(w)
                except: w=2
                print("429 wait",w,body[:100]); time.sleep(w+0.2); continue
            print("err",e.code,body[:150]); time.sleep(1)
        except Exception as e:
            print("exc",e); time.sleep(1)
    raise SystemExit("failed "+path)
orders=[];dups=0;seen=set()
p=1;path="/orders?page=1"
while path:
    d=get(path)
    for o in d["items"]:
        if o["id"] in seen: dups+=1
        else: seen.add(o["id"]); orders.append(o)
    path=d["next"]
print("pages",d["total_pages"],"listed",len(orders)+dups,"distinct",len(orders),"dups",dups)
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
q=[]
for o in orders:
    dt=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if dt.tzinfo is None: print("naive",o)
    if o["status"]=="shipped" and lo<=dt.astimezone(timezone.utc)<hi: q.append(o)
cust={}
for o in q:
    c=o["customer_id"]
    if c not in cust: cust[c]=get("/customers/"+c)
reg={"north":0,"south":0,"east":0,"west":0};n=0
for o in q:
    c=cust[o["customer_id"]]
    if c is None: print("missing customer",o); continue
    num=o["amount_cents"]*(100-c["discount_pct"])
    v=(num+50)//100
    reg[c["region"]]+=v;n+=1
res={"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dups,"by_region":reg}
json.dump(res,open("/workspace/result.json","w"),indent=2)
print(res, set(o["status"] for o in orders))
EOF
